  "privacy.eyebrow": "Organisation · Data processing",
  "privacy.title": "What is kept, why, and <em>for how long</em>",
  "privacy.tabStatus": "Register · erasure · backup",
  "privacy.tabLegal": "Legal mapping (PIPA · Medical Service Act)",
  "privacy.statusNote": "Workspace <code id=\"privacy-wsid\">—</code>. Items marked “encrypted: yes” are stored as ciphertext only, under the workspace key (AES-GCM). Items past their retention period are purged automatically at every unlock.",
  "privacy.cloudNote": "<strong>What the server can and cannot see (PoC).</strong> The clinic server (PocketBase) holds the users’ <strong>names and roles</strong> (readable by <strong>anyone who knows the URL</strong>, so the dropdown works before login), bcrypt hashes of PIN-derived passwords, the master key wrapped under each user’s PIN (ciphertext), the intake cards’ ciphertext and status, and <strong>the ciphertext of the whole clinic dataset</strong> (roster · patient register · claim batches · appeals · trackers · tariff · institution profile · activity log · licence photos — sealed under the clinic key, so the server sees only key names, sizes, modification times and the editor’s id). The server cannot see PINs, the master key or any value. A server administrator can, however, delete users or ciphertext, and any logged-in member can overwrite any item (availability and integrity are not protected). Screen settings, lock settings and the AI note stay on this device only.",
  "privacy.destroyServer": "Also destroy this clinic’s server data (Director · disappears on every device)",
  "privacy.wipePromptServer": "This destroys all data, attachments and encryption keys on this device AND marks every ciphertext of the clinic on the server as deleted — the other devices empty themselves on their next sync. Server accounts (users · PINs) remain. It cannot be undone and cannot be recovered without a backup.\n\nType “파기” (or DESTROY) to continue.",
  "privacy.sync.h": "Server sync — every device · E2E ciphertext · last write wins per item",
  "privacy.sync.note": "Every item except screen settings, lock settings and the AI note is uploaded as ciphertext sealed under the clinic key and opens on any other device. When two devices edit the same item, the <strong>last write by server time</strong> stays and this device’s losing value is kept below (last 20) — <strong>Restore</strong> brings it back. Offline edits queue in an encrypted outbox and are sent once reconnected.",
  "privacy.sync.line": "{state} · last sync {t} · {k} server items · {f} attachments · {p} pending · {c} conflicts",
  "privacy.sync.stateOn": "Connected", "privacy.sync.stateOff": "Offline", "privacy.sync.stateSyncing": "Syncing", "privacy.sync.stateLocal": "Local only (not logged in)",
  "privacy.sync.now": "Sync now", "privacy.sync.clear": "Clear conflict log",
  "privacy.sync.thAt": "When", "privacy.sync.thKey": "Item", "privacy.sync.thBy": "Overwritten by", "privacy.sync.thLosing": "This device’s value (not applied)",
  "privacy.sync.restore": "Restore", "privacy.sync.empty": "No conflicts", "privacy.sync.deletedVal": "(deleted on this device)",
  "privacy.sync.msgNow": "Synced", "privacy.sync.msgOffline": "Cannot reach the server — changes stay in the outbox", "privacy.sync.msgCleared": "Conflict log cleared",
  "privacy.sync.msgRestored": "This device’s value restored and sent to the server", "privacy.sync.logRestored": "Sync conflict value restored",
